with flattened as (select id, plan, effective_from, explode(tier_limits) as element from price_tiers) select id, effective_from, element, stddev_samp(element) over w_running as plan_stddev_samp_element, count(element) over w_running as plan_count_element, avg(element) over w_running as plan_avg_element, dense_rank() over (partition by plan order by element nulls first) as element_dense_rank, cume_dist() over w_part as element_cume_dist from flattened window w_running as (partition by plan), w_part as (partition by plan order by element desc nulls first);
